using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);

// Load data
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

// Build pipeline: map "Yes"/"No" to boolean Label, encode Region, concatenate features
var pipeline = mlContext.Transforms.CustomMapping<CustomerData, ChurnLabel>(
        (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
        contractName: "ChurnMapping")
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

// Train on full data
var model = pipeline.Fit(data);

// Evaluate via cross-validation
try
{
    var cvResults = mlContext.BinaryClassification.CrossValidate(data, pipeline, numberOfFolds: 2, labelColumnName: "Label");
    var avgAuc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);
    var avgF1 = cvResults.Average(r => r.Metrics.F1Score);
    Console.WriteLine($"Cross-validated AUC: {avgAuc:F4}, F1: {avgF1:F4}");
}
catch (Exception ex) when (ex is ArgumentOutOfRangeException or InvalidOperationException)
{
    Console.WriteLine("Dataset too small for reliable cross-validation metrics. Add more data for evaluation.");
}

// Save model
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
mlContext.Model.Save(model, data.Schema, modelPath);

// Register prediction engine pool
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new { WillChurn = prediction.PredictedLabel, Probability = prediction.Probability });
});

app.Run();

